{"path":"events.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Gatherings — {{BUSINESS_NAME}}</title>
  <style>
    :root{
      --bg:#0f1113; --card:#0b0d0f; --muted:#9aa3a6; --accent:#7be3d1; --accent-2:#6bd3ff; --glass:rgba(255,255,255,0.04); --radius:14px;
      --ff-sans: system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial;
    }
    *{box-sizing:border-box}
    body{font-family:var(--ff-sans); margin:0; color:#e9f6f4; background:linear-gradient(180deg, #071014 0%, #071316 60%); -webkit-font-smoothing:antialiased;}
    header{display:flex;align-items:center;justify-content:space-between;padding:20px 28px}
    .brand{display:flex;gap:12px;align-items:center}
    .logo{width:48px;height:48px;border-radius:12px;background:linear-gradient(135deg,var(--accent),var(--accent-2));display:flex;align-items:center;justify-content:center;font-weight:700;color:#052;box-shadow:0 6px 20px rgba(11,197,170,0.08)}
    nav a{color:var(--muted);text-decoration:none;margin:0 10px;font-weight:600}
    nav a:hover{color:var(--accent)}
    .wrap{max-width:1100px;margin:24px auto;padding:24px}

    /* hero */
    .hero{position:relative;background:linear-gradient(180deg, rgba(11,13,15,0.6), rgba(3,5,6,0.6));border-radius:var(--radius);padding:28px;overflow:hidden}
    .hero-grid{display:grid;grid-template-columns:1fr 360px;gap:20px;align-items:start}
    .hero h1{margin:0 0 8px;font-size:28px;letter-spacing:-0.02em}
    .hero p.lead{margin:0;color:var(--muted)}
    .svg-deco{position:absolute;right:-120px;top:-30px;opacity:0.12;transform:rotate(8deg)}
    .card{background:linear-gradient(180deg, rgba(255,255,255,0.02), transparent);padding:18px;border-radius:12px;border:1px solid rgba(255,255,255,0.03)}

    /* next event */
    .next{display:flex;flex-direction:column;gap:12px}
    .next .when{font-weight:800;font-size:20px}
    .muted{color:var(--muted);font-size:14px}
    .cta{display:inline-block;background:var(--accent);color:#042;padding:10px 14px;border-radius:10px;text-decoration:none;font-weight:700}

    /* calendar list */
    .calendar{margin-top:18px;display:grid;gap:12px}
    .event-row{display:flex;justify-content:space-between;align-items:center;padding:12px;border-radius:10px;background:rgba(255,255,255,0.02)}
    .event-meta{display:flex;gap:12px;align-items:center}
    .date-pill{min-width:72px;background:rgba(255,255,255,0.03);padding:8px;border-radius:10px;text-align:center}
    .event-title{font-weight:700}

    /* mood selector */
    .moods{display:flex;gap:10px;flex-wrap:wrap}
    .mood{padding:10px 12px;border-radius:10px;background:var(--glass);border:1px solid rgba(255,255,255,0.02);cursor:pointer;color:var(--muted)}
    .mood.active{background:linear-gradient(90deg,var(--accent),var(--accent-2));color:#052;font-weight:800;transform:translateY(-4px);box-shadow:0 10px 30px rgba(11,197,170,0.08)}

    .recommend{margin-top:14px;padding:14px;border-radius:10px;background:linear-gradient(180deg, rgba(11,13,15,0.22), rgba(11,13,15,0.06));border:1px solid rgba(255,255,255,0.03)}
    .method-title{font-weight:800;margin:0 0 6px}
    .method-desc{margin:0;color:var(--muted)}

    footer{margin:38px auto 80px;max-width:1100px;padding:20px;color:var(--muted);text-align:center}

    /* small */
    .contra{font-size:13px;color:#f6c1c1;background:rgba(255,128,128,0.04);padding:12px;border-radius:10px;border:1px solid rgba(255,128,128,0.06)}

    @media(max-width:880px){.hero-grid{grid-template-columns:1fr;}.logo{width:44px;height:44px}}
  </style>
</head>
<body>
  <header>
    <div class="brand">
      <div class="logo">SB</div>
      <div>
        <div style="font-weight:800">{{BUSINESS_NAME}}</div>
        <div style="font-size:13px;color:var(--muted)">{{TAGLINE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Gather</a>
      <a href="private-sessions.html">Private Work</a>
      <a href="pricing.html">Plans</a>
      <a href="about.html">Who</a>
      <a href="book.html">Reserve</a>
    </nav>
  </header>

  <main class="wrap">
    <section class="hero">
      <svg class="svg-deco" width="420" height="420" viewBox="0 0 420 420" xmlns="http://www.w3.org/2000/svg">
        <defs>
          <linearGradient id="g" x1="0" x2="1"><stop offset="0" stop-color="#7be3d1"/><stop offset="1" stop-color="#6bd3ff"/></linearGradient>
          <pattern id="p" width="80" height="80" patternUnits="userSpaceOnUse">
            <rect width="80" height="80" fill="rgba(255,255,255,0)"/>
            <circle cx="20" cy="20" r="6" fill="url(#g)"/>
            <circle cx="60" cy="60" r="6" fill="rgba(255,255,255,0.05)"/>
          </pattern>
        </defs>
        <rect width="420" height="420" fill="url(#p)" opacity="0.95" rx="48"/>
      </svg>

      <div class="hero-grid">
        <div>
          <h1>Upcoming gatherings to re-tune your rhythm</h1>
          <p class="lead">We shape open listening sessions and short-format sound studios. Drop in to breathe differently — sessions tuned to evenings, mornings, and mid-day turns.</p>

          <div style="margin-top:18px" class="card">
            <div style="display:flex;justify-content:space-between;align-items:center">
              <div>
                <div class="muted">Next gathering</div>
                <div class="when">Saturday • Feb 28 • 6:30pm</div>
                <div class="muted">Limited seating in {{CITY}}, {{STATE}}</div>
              </div>
              <div style="text-align:right">
                <a class="cta" href="book.html" id="nextCta">Reserve a Spot</a>
                <div style="font-size:12px;color:var(--muted);margin-top:8px">Pay-what-feels-right or use membership</div>
              </div>
            </div>

            <div style="margin-top:12px;display:flex;gap:10px;align-items:center">
              <svg width="64" height="64" viewBox="0 0 64 64" style="border-radius:10px;background:rgba(255,255,255,0.02);padding:8px">
                <circle cx="32" cy="32" r="10" fill="rgba(107,211,255,0.16)"/>
                <g stroke="#7be3d1" stroke-width="1.6" fill="none"><path d="M10 42c8-14 36-20 44-6"/></g>
              </svg>
              <div>
                <div style="font-weight:800">Open Resonance • 60 min</div>
                <div class="muted">Guided tones, long-form bowls, breath prompts</div>
              </div>
            </div>

          </div>

          <div style="margin-top:16px" class="card">
            <div class="muted">Pick how you feel — find an approach</div>
            <div style="margin-top:10px" class="moods" id="moodGroup">
              <div class="mood" data-key="rattled">Rattled</div>
              <div class="mood" data-key="wired">Wired</div>
              <div class="mood" data-key="quiet">Quiet</div>
              <div class="mood" data-key="heavy">Heavy</div>
              <div class="mood" data-key="curious">Curious</div>
            </div>
            <div class="recommend" id="recommend">
              <div class="method-title">Harmonic Drift — a gentle unfold</div>
              <div class="method-desc">A slow, layered sequence of bowls and breath prompts designed to ease the edge and re-center attention.</div>
              <div style="margin-top:10px"><a class="cta" href="book.html" id="moodCta">Join the next session</a></div>
            </div>
          </div>

          <div style="margin-top:14px" class="contra">Contraindications: Sound sessions are generally safe but may not be appropriate for those with epilepsy sensitive to rhythmic stimuli, certain inner-ear conditions, recent head or neck injuries, or if you are pregnant and advised otherwise. If you have implants, pacemakers, or other medical devices, consult a clinician before attending. Contact us at {{EMAIL}} or {{PHONE}} for specifics.</div>
        </div>

        <aside>
          <div class="card next">
            <div style="font-size:13px;color:var(--muted)">Next event — spotlight</div>
            <div class="when">Saturday • Feb 28 • 6:30pm</div>
            <div class="muted">{{CITY}}, {{STATE}} • Doors 15 min early</div>
            <div style="margin-top:10px">Theme: Nightframe — a mixed tuning set for softening the end of day.</div>
            <div style="margin-top:10px;display:flex;gap:8px">
              <a class="cta" href="book.html">Book a spot</a>
              <a href="events.html" style="color:var(--muted);align-self:center;text-decoration:none">See all</a>
            </div>
          </div>

          <div style="margin-top:16px" class="card">
            <div style="font-weight:800">This month — calendar</div>
            <div class="calendar" id="calendarList">
              <!-- JS will populate -->
            </div>
          </div>

        </aside>
      </div>
    </section>
  </main>

  <footer>
    <div>{{BUSINESS_NAME}} — tuned gatherings and short-form sound labs. Questions? <a href="contact.html" style="color:var(--accent)">{{EMAIL}}</a> • <a href="tel:{{PHONE}}" style="color:var(--accent)">{{PHONE}}</a></div>
  </footer>

  <script>
    // Simple calendar data (would be dynamic server-side normally)
    const events = [
      {date:'2026-02-28', day:'Sat', time:'18:30', title:'Nightframe — Open Resonance', desc:'60 min guided sound assembly'},
      {date:'2026-03-07', day:'Sat', time:'10:30', title:'Morning Wash — Short Form', desc:'40 min gentle re-tune'},
      {date:'2026-03-14', day:'Sat', time:'19:00', title:'Pulse Collective — focused tones', desc:'75 min deep listening'},
      {date:'2026-03-21', day:'Sun', time:'16:00', title:'Afternoon Ease — mixed bowls', desc:'50 min restorative set'}
    ];

    const calendarRoot = document.getElementById('calendarList');
    events.forEach(ev=>{
      const el = document.createElement('div'); el.className='event-row';
      el.innerHTML = `<div class=event-meta><div class=date-pill><div style=font-weight:800>${ev.day}</div><div style=color:var(--muted);font-size:13px>${ev.time}</div></div><div><div class=event-title>${ev.title}</div><div class=muted style=font-size:13px>${ev.desc}</div></div></div><div><a href='book.html' class='cta' style='padding:8px 10px'>Reserve</a></div>`;
      calendarRoot.appendChild(el);
    });

    // Mood-to-Method: maps
    const methods = {
      rattled:{title:'Deep Wash — smoothing edges',desc:'Rhythmic bowls with slow breath scaffolding to settle a scattered nervous system.',cta:'Reserve a Wash'},
      wired:{title:'Focused Tone — narrowed attention',desc:'Short, pointed sequences to anchor present focus and quiet racing thought.',cta:'Book Focused Tone'},
      quiet:{title:'Open Resonance — spacious listening',desc:'An expansive, meditative space with long bowls and silence between tones.',cta:'Join Open Resonance'},
      heavy:{title:'Lift Sequence — lightening layers',desc:'Harmonic rises and gentle overtones to invite uplift and buoyancy.',cta:'Book Lift Sequence'},
      curious:{title:'Exploratory Set — curious tuning',desc:'Playful interludes and tonal experiments for gentle curiosity.',cta:'Try an Exploratory Set'}
    };

    const moodGroup = document.getElementById('moodGroup');
    const recommend = document.getElementById('recommend');
    const moodCta = document.getElementById('moodCta');
    moodGroup.addEventListener('click', (e)=>{
      const el = e.target.closest('.mood'); if(!el) return;
      [...moodGroup.children].forEach(c=>c.classList.remove('active'));
      el.classList.add('active');
      const key = el.getAttribute('data-key');
      const m = methods[key];
      recommend.querySelector('.method-title').textContent = m.title;
      recommend.querySelector('.method-desc').textContent = m.desc;
      moodCta.textContent = m.cta;
      // change main next CTA phrasing slightly
      document.getElementById('nextCta').textContent = (key==='wired') ? 'Grab a Focus Seat' : 'Reserve a Spot';
    });

    // Pre-select a mood based on simple time heuristic
    (function preSelect(){
      const hour = new Date().getHours();
      const pick = hour>=18? 'rattled' : (hour<10? 'quiet':'curious');
      const el = moodGroup.querySelector(`[data-key="${pick}"]`);
      if(el) el.click();
    })();
  </script>
</body>
</html>"} 
{"path":"private-sessions.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Private Sessions — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#081018;--muted:#9fb0b3;--accent:#7be3d1;--accent-2:#6bd3ff;--card:#0b0d0f;--radius:12px;}
    *{box-sizing:border-box}
    body{margin:0;font-family:system-ui, -apple-system, 'Segoe UI', Roboto, Arial;color:#e9f6f4;background:linear-gradient(180deg,#031018 0%,#041418 60%)}
    header{display:flex;justify-content:space-between;align-items:center;padding:18px 28px}
    .logo{width:42px;height:42px;border-radius:10px;background:linear-gradient(135deg,var(--accent),var(--accent-2));display:flex;align-items:center;justify-content:center;font-weight:800;color:#052}
    nav a{color:var(--muted);margin-left:12px;text-decoration:none;font-weight:700}

    .container{max-width:980px;margin:20px auto;padding:20px}
    .grid{display:grid;grid-template-columns:1fr 320px;gap:18px}
    .panel{background:rgba(255,255,255,0.02);padding:18px;border-radius:var(--radius);border:1px solid rgba(255,255,255,0.03)}
    h1{margin:0 0 8px}
    .sub{color:var(--muted);margin:0 0 18px}

    .mood-set{display:flex;gap:8px;flex-wrap:wrap}
    .mood-button{padding:10px 12px;border-radius:10px;border:1px solid rgba(255,255,255,0.03);background:transparent;color:var(--muted);cursor:pointer}
    .mood-button.active{background:linear-gradient(90deg,var(--accent),var(--accent-2));color:#042;font-weight:800;transform:scale(1.02)}

    .method-preview{margin-top:14px;padding:12px;border-radius:10px;background:linear-gradient(180deg, rgba(11,13,15,0.16), transparent);}
    .method-title{font-weight:800}
    .method-bullets{margin-top:8px;color:var(--muted)}

    .form-cta{margin-top:14px}
    .btn{display:inline-block;padding:10px 14px;border-radius:10px;text-decoration:none;font-weight:800}
    .btn-primary{background:var(--accent);color:#042}
    .btn-secondary{background:transparent;border:1px solid rgba(255,255,255,0.04);color:var(--muted)}

    .note{font-size:13px;color:var(--muted);margin-top:10px}

    .solo-info{font-size:14px}

    @media(max-width:880px){.grid{grid-template-columns:1fr}.logo{width:40px;height:40px}}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;gap:12px;align-items:center">
      <div class="logo">PS</div>
      <div style="font-weight:800">{{BUSINESS_NAME}}</div>
    </div>
    <nav>
      <a href="index.html">Gather</a>
      <a href="events.html">Calendar</a>
      <a href="pricing.html">Plans</a>
      <a href="contact.html">Help</a>
    </nav>
  </header>

  <main class="container">
    <div class="grid">
      <div>
        <div class="panel">
          <h1>Private sessions — tailored resonance</h1>
          <p class="sub">One-on-one or small group sessions tuned for an individual nervous system. We craft a plan that meets you where you are.</p>

          <div>
            <div style="font-weight:800">How are you today?</div>
            <div class="mood-set" id="privateMood">
              <button class="mood-button" data-key="tense">Tense</button>
              <button class="mood-button" data-key="scattered">Scattered</button>
              <button class="mood-button" data-key="numb">Numb</button>
              <button class="mood-button" data-key="open">Open</button>
              <button class="mood-button" data-key="grieving">Grieving</button>
            </div>

            <div class="method-preview" id="privateMethod">
              <div class="method-title">Focused Resonance — a quiet scaffold</div>
              <div class="method-bullets">Sessions use tuned bowls with calibrated pacing. Expect short breath cues, tonal anchors, and intentional silences.</div>
              <div class="note">Typical length: 60–90 minutes. We adapt pace and intensity to your comfort.</div>

              <div class="form-cta">
                <a class="btn btn-primary" href="book.html" id="privateCta">Request a Private Session</a>
                <a class="btn btn-secondary" href="contact.html">Ask a Question</a>
              </div>
            </div>

            <div style="margin-top:12px;color:var(--muted);font-size:13px">Contraindications: If you have photosensitive epilepsy, inner-ear injury, recent head trauma, or active psychiatric crisis, consult medical advice before booking. Mention implants, pacemakers, or pregnancy when you book. For detailed conversation, email {{EMAIL}} or call {{PHONE}}.</div>
          </div>

        </div>

        <div style="margin-top:14px" class="panel">
          <div style="font-weight:800">What to expect</div>
          <ul style="margin-top:8px;color:var(--muted)">
            <li>Brief intake to set intention</li>
            <li>Customized tonal sequence</li>
            <li>Post-session notes and adjustments for next visit</li>
          </ul>
        </div>
      </div>

      <aside>
        <div class="panel solo-info">
          <div style="font-weight:800">Private formats</div>
          <div style="margin-top:8px;color:var(--muted)">Choose a guided solo session, a cued duo session (partner with cues), or small-group therapy-oriented sessions (up to 4).</div>

          <div style="margin-top:12px;font-weight:800">Duration & logistics</div>
          <div style="margin-top:8px;color:var(--muted)">Sessions usually 60–90 minutes depending on intake and requested depth. We can arrange home visits within {{CITY}} and select neighborhoods.</div>

          <div style="margin-top:12px">
            <div style="font-weight:800">Quick pricing</div>
            <div style="margin-top:6px;color:var(--muted)">From $120 for 60 minutes (packages and memberships available) — see <a href="pricing.html" style="color:var(--accent)">Plans</a>.</div>
          </div>

          <div style="margin-top:12px">
            <a class="btn btn-primary" href="book.html">Schedule a Private</a>
          </div>
        </div>
      </aside>
    </div>
  </main>

  <script>
    const mapping = {
      tense:{title:'Slow Anchoring — gentle deceleration',desc:'Long, steady bowls and soft tempoing to invite down-regulation. Useful for muscular tension and anxious narrowness.',cta:'Request Slow Anchor'},
      scattered:{title:'Tone Focus — brief centering',desc:'Short sequences with tonal anchors to gather attention and slow mental wandering.',cta:'Book a Focus'},
      numb:{title:'Subtle Lift — micro-stimulus',desc:'Layered, warm overtones to invite corporeal sensation and return to felt presence.',cta:'Book Subtle Lift'},
      open:{title:'Spacious Listening — patient holding',desc:'Broader sonic space with longer silences and listening intervals; ideal for contemplative reset.',cta:'Reserve Spacious Listening'},
      grieving:{title:'Tender Support — held transitions',desc:'Soft, low frequencies and held pauses to allow emotion within safe sonic framing.',cta:'Request Tender Support'}
    };

    const root = document.getElementById('privateMood');
    const preview = document.getElementById('privateMethod');
    const cta = document.getElementById('privateCta');

    root.addEventListener('click', (ev)=>{
      const btn = ev.target.closest('.mood-button'); if(!btn) return;
      [...root.querySelectorAll('.mood-button')].forEach(b=>b.classList.remove('active'));
      btn.classList.add('active');
      const key = btn.getAttribute('data-key');
      const m = mapping[key];
      preview.querySelector('.method-title').textContent = m.title;
      preview.querySelector('.method-bullets').textContent = m.desc;
      cta.textContent = m.cta;
      // subtext tweak depending on mood
      preview.querySelector('.note').textContent = (key==='grieving')? 'Longer containers available on request.' : 'Typical length: 60–90 minutes. We adapt pace to your comfort.';
    });

    // gentle preselect
    (function(){
      const now = new Date().getHours();
      const pick = (now>20)? 'numb' : (now<9? 'tense' : 'open');
      const el = root.querySelector(`[data-key="${pick}"]`);
      if(el) el.click();
    })();
  </script>
</body>
</html>"} 
{"path":"pricing.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Plans — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#071018;--card:#07121a;--muted:#9fafb2;--accent:#7be3d1;--accent-2:#6bd3ff;--radius:14px}
    *{box-sizing:border-box}
    body{margin:0;font-family:system-ui, -apple-system, 'Segoe UI', Roboto, Arial;color:#e9f6f4;background:linear-gradient(180deg,#021014 0%,#041316 70%)}
    header{display:flex;justify-content:space-between;align-items:center;padding:20px 28px}
    .logo{width:44px;height:44px;border-radius:10px;background:linear-gradient(135deg,var(--accent),var(--accent-2));display:flex;align-items:center;justify-content:center;color:#042;font-weight:900}
    nav a{color:var(--muted);margin-left:12px;text-decoration:none}

    .wrap{max-width:1100px;margin:24px auto;padding:20px}
    h1{margin:6px 0 0}
    .lead{color:var(--muted)}

    .toggle{display:inline-flex;background:rgba(255,255,255,0.02);padding:6px;border-radius:12px;border:1px solid rgba(255,255,255,0.03)}
    .toggle button{background:transparent;border:0;color:var(--muted);padding:8px 12px;border-radius:10px;cursor:pointer;font-weight:700}
    .toggle button.active{background:linear-gradient(90deg,var(--accent),var(--accent-2));color:#042;transform:translateY(-2px)}

    .plans{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-top:18px}
    .plan{background:linear-gradient(180deg, rgba(255,255,255,0.02), transparent);padding:18px;border-radius:12px;border:1px solid rgba(255,255,255,0.03)}
    .plan .name{font-weight:900}
    .price{font-size:28px;font-weight:900;margin-top:6px}
    .muted{color:var(--muted)}
    .features{margin-top:10px;color:var(--muted)}
    .plan .cta{margin-top:12px;display:inline-block;padding:10px 12px;border-radius:10px;background:var(--accent);color:#042;font-weight:800;text-decoration:none}

    .note{margin-top:16px;color:var(--muted);font-size:13px}
    .contra{margin-top:12px;color:#f6c1c1;background:rgba(255,128,128,0.04);padding:10px;border-radius:10px}

    @media(max-width:900px){.plans{grid-template-columns:1fr}header{padding:12px}}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;gap:12px;align-items:center">
      <div class="logo">PL</div>
      <div style="font-weight:800">{{BUSINESS_NAME}}</div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="events.html">Calendar</a>
      <a href="private-sessions.html">Private</a>
      <a href="contact.html">Contact</a>
    </nav>
  </header>

  <main class="wrap">
    <h1>Memberships & Packs</h1>
    <p class="lead">Choose a steady plan or a flexible package. Toggle between monthly billing and packaged sessions—numbers animate to show the effective rate.</p>

    <div style="display:flex;align-items:center;justify-content:space-between;gap:12px;margin-top:18px">
      <div class="toggle" role="tablist" id="billingToggle">
