  <script>
    // Pricing comparator logic with animated numbers
    const toggle = document.getElementById('billingToggle');
    const buttons = toggle.querySelectorAll('button');
    const nums = document.querySelectorAll('.num');

    function animateNumber(el, start, end, duration=600){
      const startTime = performance.now();
      function frame(now){
        const t = Math.min((now - startTime)/duration, 1);
        const ease = t<0.5? 2*t*t : -1 + (4 - 2*t)*t; // simple ease
        const val = start + (end - start)*ease;
        el.textContent = '$' + (Math.round(val*100)/100).toLocaleString(undefined,{minimumFractionDigits: (end%1?2:0)}).replace('.00','');
        if(t<1) requestAnimationFrame(frame);
      }
      requestAnimationFrame(frame);
    }

    function switchMode(mode){
      nums.forEach(n=>{
        const monthly = parseFloat(n.getAttribute('data-monthly'));
        const pack = parseFloat(n.getAttribute('data-package'));
        const from = parseFloat(n.textContent.replace(/[^0-9\.]/g,'')) || monthly;
        const to = (mode==='monthly')? monthly : pack;
        animateNumber(n, from, to);
      });
      // CTA phrasing shift
      document.querySelectorAll('.plan .cta').forEach(a=>{
        const base = a.getAttribute('data-cta');
        a.textContent = (mode==='monthly')? base.replace(/(Explorer|Pulse|Anchor)/,'Join') : base.replace(/(Explorer|Pulse|Anchor)/,'Purchase');
      });
    }

    buttons.forEach(b=>b.addEventListener('click', ()=>{
      buttons.forEach(x=>x.classList.remove('active'));
      b.classList.add('active');
      const mode = b.getAttribute('data-mode');
      switchMode(mode);
    }));

    // initial state
    (function(){
      // set initial displayed numbers from data-monthly
      nums.forEach(n=>{
        const val = n.getAttribute('data-monthly');
        n.textContent = '$' + val;
      });
    })();
  </script>
